```sql
ALTER TABLE reviews ADD COLUMN embedding_new vector(512);

-- backfill in batches from the application, then:
CREATE INDEX CONCURRENTLY reviews_embedding_new_hnsw_idx
    ON reviews
    USING hnsw (embedding_new vector_cosine_ops);

